  return (
    <AccordionPrimitive.Header>
      <AccordionPrimitive.Trigger
        {...rest}
        className={clsx('lg-button lg-accordion-trigger', className)}
      >
        <span>{children}</span>
        <svg
          viewBox="0 0 20 20"
