'use client';

import { Slot, Slottable } from '@radix-ui/react-slot';
import clsx from 'clsx';
import {
  cloneElement,
  forwardRef,
  isValidElement,
  use,
  useCallback,
  useEffect,
  useMemo,
  useRef,
} from 'react';
import type { CSSProperties, ReactNode } from 'react';
import { mergeRefs } from './lib/merge-refs';
import { useGlassScenePane } from './lib/scene-context';
import { useLensFilter } from './lib/use-refraction-filter';
import { useOptionalPreferences } from './glass-provider';

export type ButtonVariant = 'primary' | 'prominent' | 'ghost' | 'soft';

export type ButtonSize = 'sm' | 'md' | 'lg';

type ButtonPreset = 'control' | 'showcase';

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Renders the single child element, such as a link, with the button's material. Links cannot be disabled. */
  asChild?: boolean;
  /** Chromium edge lens over the frost. On by default for filled variants. */
  lens?: boolean;
  preset?: ButtonPreset;
  variant?: ButtonVariant;
  size?: ButtonSize;
}

const VARIANT_CLASS: Record<ButtonVariant, string> = {
  primary: 'lg-button--primary',
  prominent: 'lg-button--prominent',
  ghost: 'lg-button--ghost',
  soft: 'lg-button--soft',
};

const SIZE_CLASS: Record<ButtonSize, string> = {
  sm: 'lg-button--sm',
  md: 'lg-button--md',
  lg: 'lg-button--lg',
};

const REACT_LAZY = Symbol.for('react.lazy');

// A server component's element can reach a client component as a lazy reference, which React 19
// does in development; its payload is the chunk the element arrives in, a kind of Promise. Slot
// unwraps one before slotting it, so the label has to as well.
function isLazyNode(node: unknown): node is { _payload: Promise<ReactNode> } {
  return (
    node instanceof Object &&
    '$$typeof' in node &&
    node.$$typeof === REACT_LAZY &&
    '_payload' in node &&
    node._payload instanceof Promise
  );
}

// The label sits above the material layers, so a slotted child's content moves into it.
function withLabel(children: ReactNode) {
  if (!isValidElement<{ children?: ReactNode }>(children)) return children;

  return cloneElement(
    children,
    undefined,
    <span className="lg-button__label">{children.props.children}</span>,
  );
}

export const GlassButton = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      asChild = false,
      className,
      preset = 'control',
      variant = 'primary',
      lens = variant !== 'ghost',
      size = 'md',
      type,
      disabled = false,
      onPointerLeave,
      onPointerCancel,
      onPointerDown,
      onPointerUp,
      onBlur,
      onKeyDown,
      onKeyUp,
      style,
      children,
      ...rest
    },
    forwardedRef,
  ) => {
    const { preferences } = useOptionalPreferences();
    const reduceMotion = Boolean(preferences?.reduceMotion);
    const reduceTransparency = Boolean(preferences?.reduceTransparency);
    const buttonRef = useRef<HTMLButtonElement | null>(null);
    const bloomRef = useRef<HTMLSpanElement | null>(null);
    const ref = useMemo(() => mergeRefs(forwardedRef, buttonRef), [forwardedRef]);

    const releasePress = useCallback((target: HTMLButtonElement) => {
      target.style.setProperty('--lg-press', '0');
      target.dataset.pressed = 'false';
    }, []);

    // A press lights the glass from the point it lands and the light spreads
    // outward, as it does through Apple's glass under a fingertip.
    const bloom = useCallback(
      (target: HTMLElement, x: number, y: number) => {
        const element = bloomRef.current;

        if (!element || reduceMotion) return;

        element.style.setProperty('--lg-bloom-x', `${x}px`);
        element.style.setProperty('--lg-bloom-y', `${y}px`);
        element.style.setProperty(
          '--lg-bloom-size',
          `${Math.max(target.offsetWidth, target.offsetHeight) * 2.4}px`,
        );
        element.animate?.(
          [
            { opacity: 0, transform: 'scale(0.08)' },
            { opacity: 1, transform: 'scale(0.42)', offset: 0.16 },
            { opacity: 0, transform: 'scale(1)' },
          ],
          { duration: 720, easing: 'cubic-bezier(0.22, 0.8, 0.3, 1)' },
        );
      },
      [reduceMotion],
    );

    const handlePointerLeave = useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerLeave?.(event);
        event.currentTarget.releasePointerCapture?.(event.pointerId);
        releasePress(event.currentTarget);
      },
      [onPointerLeave, releasePress],
    );

    const handlePointerCancel = useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerCancel?.(event);
        event.currentTarget.releasePointerCapture?.(event.pointerId);
        releasePress(event.currentTarget);
      },
      [onPointerCancel, releasePress],
    );

    const handlePointerDown = useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerDown?.(event);

        if (event.defaultPrevented || disabled) return;
        const target = event.currentTarget;
        const bounds = target.getBoundingClientRect();
        // A scaled button maps client pixels back to its own, so the bloom starts under the finger.
        const scale = bounds.width / Math.max(target.offsetWidth, 1) || 1;

        target.setPointerCapture?.(event.pointerId);
        target.style.setProperty('--lg-press', '1');
        target.dataset.pressed = 'true';
        bloom(target, (event.clientX - bounds.left) / scale, (event.clientY - bounds.top) / scale);
      },
      [bloom, disabled, onPointerDown],
    );

    const handlePointerUp = useCallback(
      (event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerUp?.(event);
        event.currentTarget.releasePointerCapture?.(event.pointerId);
        event.currentTarget.style.setProperty('--lg-press', '0');
        event.currentTarget.dataset.pressed = 'false';
      },
      [onPointerUp],
    );

    const handleBlur = useCallback(
      (event: React.FocusEvent<HTMLButtonElement>) => {
        onBlur?.(event);
        releasePress(event.currentTarget);
      },
      [onBlur, releasePress],
    );

    const handleKeyDown = useCallback(
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        onKeyDown?.(event);

        if (event.defaultPrevented || disabled) return;

        if (event.key === ' ' || event.key === 'Enter') {
          const target = event.currentTarget;

          target.style.setProperty('--lg-press', '1');
          target.dataset.pressed = 'true';

          if (!event.repeat) bloom(target, target.offsetWidth / 2, target.offsetHeight / 2);
        }
      },
      [bloom, disabled, onKeyDown],
    );

    const handleKeyUp = useCallback(
      (event: React.KeyboardEvent<HTMLButtonElement>) => {
        onKeyUp?.(event);

        if (event.key === ' ' || event.key === 'Enter') {
          event.currentTarget.style.setProperty('--lg-press', '0');
          event.currentTarget.dataset.pressed = 'false';
        }
      },
      [onKeyUp],
    );

    // A button disabled mid-press lets go of it.
    useEffect(() => {
      if (disabled && buttonRef.current) releasePress(buttonRef.current);
    }, [disabled, releasePress]);

    // Inside a GlassScene the canvas draws this glass. Ghost buttons have none.
    useGlassScenePane(buttonRef, variant !== 'ghost');

    const lensFilter = useLensFilter(buttonRef, {
      enabled: lens && !disabled && !reduceTransparency,
      signature: `${preferences?.theme}:${preferences?.mode}:${preferences?.quality}:${preferences?.thickness}`,
    });

    // Without this, the client renders a lazy child's content outside the label: it sinks under
    // the material layers, and hydration fails.
    const slotted = asChild && isLazyNode(children) ? use(children._payload) : children;

    const Component = asChild ? Slot : 'button';

    return (
      <Component
        {...rest}
        ref={ref}
        type={asChild ? type : (type ?? 'button')}
        disabled={asChild ? undefined : disabled}
        className={clsx('lg-button', VARIANT_CLASS[variant], SIZE_CLASS[size], className)}
        data-lg-lens={lensFilter.active ? 'active' : undefined}
        data-lg-preset={preset}
        style={
          // SAFETY: CSSProperties has no custom-property index; this adds one string-valued property.
          lensFilter.filterStyle
            ? ({ ...style, '--lg-lens-filter': lensFilter.filterStyle } as CSSProperties)
            : style
        }
        onPointerLeave={handlePointerLeave}
        onPointerCancel={handlePointerCancel}
        onPointerDown={handlePointerDown}
        onPointerUp={handlePointerUp}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        onKeyUp={handleKeyUp}
        data-pressed="false"
      >
        <span className="lg-button__layers" aria-hidden="true">
          {lensFilter.filterElement}
          <span className="lg-button__light" />
          <span className="lg-button__distortion" />
          <span className="lg-button__tint" />
          <span className="lg-button__shine" />
          <span ref={bloomRef} className="lg-button__bloom" />
          <span className="lg-button__rim" />
        </span>
        {asChild ? (
          <Slottable>{withLabel(slotted)}</Slottable>
        ) : (
          <span className="lg-button__label">{children}</span>
        )}
      </Component>
    );
  },
);

GlassButton.displayName = 'GlassButton';

'use client';

import clsx from 'clsx';
import { forwardRef, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { HTMLAttributes, ReactNode, RefObject } from 'react';
import {
  createFrameLoop,
  createSpring,
  motionReduced,
  retuneSpring,
  stepSpring,
} from './lib/liquid-motion';
import { mergeRefs } from './lib/merge-refs';
import { GlassSurface } from './glass-surface';
import './styles/header.css';

export type GlassHeaderProps = HTMLAttributes<HTMLElement> & {
  /** A wordmark or logo, usually linked to the home page. */
  brand: ReactNode;
  /** Buttons or links at the end of the capsule. */
  actions?: ReactNode;
  /**
   * Opens out across the top of the page without glass, and condenses into the capsule once
   * the page scrolls. Fixed headers only.
   */
  condenseOnScroll?: boolean;
  /** Accessible name for the desktop and mobile navigation. */
  navigationLabel?: string;
  /** Fixed above the page by default; static keeps it in the surrounding layout. */
  position?: 'fixed' | 'static';
};

// The header condenses once the page has scrolled past this many CSS pixels, and opens again
// only when it is back at the top, so it never flickers on the threshold.
const CONDENSE_AFTER = 8;

const OPEN_WITHIN = 1;

type Feel = readonly [response: number, bounce: number];

// Condensing, the glass forms at once, before a fast scroll can carry the page under bare
// links, and the capsule gathers in behind it, settling with a slight squeeze. Opening, the bar
// spreads out without overshoot while its glass thins a little more slowly, so the material is
// seen to stretch before it goes.
const GATHER: Feel = [0.56, 0.22];

const FORM: Feel = [0.24, 0];

const SPREAD: Feel = [0.44, 0];

const THIN: Feel = [0.5, 0];

/**
 * Springs the header between the open bar at the top of the page and the capsule. It writes
 * --lg-header-spread (1 open, 0 capsule) and --lg-header-material (0 no glass, 1 glass) while
 * it moves; at rest the data-condensed state sets both. Reduced motion jumps. Until this runs,
 * the state is unknown and CSS follows the scroll position on its own.
 */
function useCondensing(headerRef: RefObject<HTMLElement | null>, enabled: boolean) {
  const [condensed, setCondensed] = useState<boolean | null>(null);
  const [moving, setMoving] = useState(false);

  useLayoutEffect(() => {
    const header = headerRef.current;

    if (!enabled || !header) return;

    const spread = createSpring(...SPREAD, 1);
    const material = createSpring(...THIN, 0);
    let target: boolean | null = null;

    const paint = () => {
      header.style.setProperty('--lg-header-spread', spread.value.toFixed(4));
      header.style.setProperty(
        '--lg-header-material',
        Math.min(Math.max(material.value, 0), 1).toFixed(4),
      );
    };

    const clear = () => {
      header.style.removeProperty('--lg-header-spread');
      header.style.removeProperty('--lg-header-material');
    };

    const loop = createFrameLoop((dt) => {
      const reduced = motionReduced();
      const spreading = stepSpring(spread, dt, reduced);
      const forming = stepSpring(material, dt, reduced);

      if (spreading || forming) {
        paint();

        return true;
      }

      clear();
      setMoving(false);

      return false;
    });

    const update = (animate: boolean) => {
      const scrolled = window.scrollY;
      const next = target ? scrolled > OPEN_WITHIN : scrolled > CONDENSE_AFTER;

      if (next === target) return;

      target = next;
      spread.target = next ? 0 : 1;
      material.target = next ? 1 : 0;
      retuneSpring(spread, ...(next ? GATHER : SPREAD));
      retuneSpring(material, ...(next ? FORM : THIN));
      setCondensed(next);

      if (animate && !motionReduced()) {
        // A jump or a fling can carry the page further than the header reaches before it
        // condenses. The glass is then there at once, so the links never sit bare on content;
        // only the shape gathers in.
        if (next && scrolled > header.getBoundingClientRect().bottom) {
          material.value = 1;
          material.velocity = 0;
        }

        // Pins the current shape inline before the new state's values apply.
        paint();
        setMoving(true);
        loop.start();

        return;
      }

      loop.stop();

      for (const spring of [spread, material]) {
        spring.value = spring.target;
        spring.velocity = 0;
      }

      clear();
      setMoving(false);
    };

    // A page that opens partway down, or returns there, starts condensed without moving.
    update(false);

    const onScroll = () => update(true);

    window.addEventListener('scroll', onScroll, { passive: true });

    return () => {
      window.removeEventListener('scroll', onScroll);
      loop.stop();
      clear();
      setMoving(false);
    };
  }, [enabled, headerRef]);

  return { condensed, moving };
}

export const GlassHeader = forwardRef<HTMLElement, GlassHeaderProps>(
  (
    {
      brand,
      actions,
      children,
      className,
      condenseOnScroll = false,
      navigationLabel = 'Primary',
      position = 'fixed',
      ...rest
    },
    forwardedRef,
  ) => {
    const headerRef = useRef<HTMLElement | null>(null);
    const ref = useMemo(() => mergeRefs(headerRef, forwardedRef), [forwardedRef]);
    const condensing = condenseOnScroll && position === 'fixed';
    const { condensed, moving } = useCondensing(headerRef, condensing);

    return (
      <header
        ref={ref}
        className={clsx('lg-header', className)}
        data-condense-on-scroll={condensing ? '' : undefined}
        data-condensed={condensing && condensed !== null ? String(condensed) : undefined}
        data-position={position}
        {...rest}
      >
        {/* The lens map is drawn for one size, so a condensing header bends light only once its
            capsule has settled; it frosts while the shape moves. */}
        <GlassSurface
          aria-hidden
          className="lg-header-glass"
          lens={!condensing || (condensed === true && !moving)}
          preset="standard"
        />
        <div className="lg-header-bar">
          <div className="lg-header-brand">{brand}</div>
          {children ? (
            <>
              <nav aria-label={navigationLabel} className="lg-header-links lg-header-desktop">
                {children}
              </nav>
              <details
                className="lg-header-menu"
                onKeyDown={(event) => {
                  if (event.key === 'Escape' && event.currentTarget.open) {
                    event.preventDefault();
                    event.currentTarget.open = false;
                    event.currentTarget.querySelector('summary')?.focus();
                  }
                }}
              >
                <summary>Menu</summary>
                <nav
                  aria-label={navigationLabel}
                  className="lg-header-links lg-header-menu-links"
                  onClick={(event) => {
                    if (event.target instanceof Element && event.target.closest('a[href]')) {
                      const menu = event.currentTarget.closest('details');

                      if (menu) {
                        menu.open = false;
                        menu.querySelector('summary')?.focus();
                      }
                    }
                  }}
                >
                  {children}
                </nav>
              </details>
            </>
          ) : null}
          {actions ? <div className="lg-header-actions">{actions}</div> : null}
        </div>
      </header>
    );
  },
);

GlassHeader.displayName = 'GlassHeader';

'use client';

import { useLayoutEffect } from 'react';
import type { RefObject } from 'react';

export type Spring = {
  value: number;
  velocity: number;
  target: number;
  stiffness: number;
  damping: number;
  precision: number;
};

/*
 * Springs take a response and a bounce: response is the period of the
 * undamped oscillation in seconds, and bounce 0 is critically damped. For
 * unit mass that is stiffness (2π / response)² and damping
 * 4π (1 - bounce) / response.
 */
export const createSpring = (
  response: number,
  bounce: number,
  value: number,
  precision = 0.001,
): Spring => ({
  value,
  velocity: 0,
  target: value,
  stiffness: ((2 * Math.PI) / response) ** 2,
  damping: (4 * Math.PI * (1 - bounce)) / response,
  precision,
});

// Changes how a spring moves without stopping it, so it carries its velocity
// into the new motion.
export const retuneSpring = (spring: Spring, response: number, bounce: number) => {
  spring.stiffness = ((2 * Math.PI) / response) ** 2;
  spring.damping = (4 * Math.PI * (1 - bounce)) / response;
};

// Semi-implicit Euler in steps of at most 1/120 s is stable for every spring
// here. Returns whether the spring is still moving.
export const stepSpring = (spring: Spring, dt: number, snap: boolean) => {
  if (snap || (spring.value === spring.target && spring.velocity === 0)) {
    spring.value = spring.target;
    spring.velocity = 0;

    return false;
  }

  const steps = Math.max(1, Math.ceil(dt * 120));
  const step = dt / steps;

  for (let index = 0; index < steps; index += 1) {
    spring.velocity +=
      (-spring.stiffness * (spring.value - spring.target) - spring.damping * spring.velocity) *
      step;
    spring.value += spring.velocity * step;
  }

  if (
    Math.abs(spring.value - spring.target) < spring.precision &&
    Math.abs(spring.velocity) < spring.precision * 10
  ) {
    spring.value = spring.target;
    spring.velocity = 0;

    return false;
  }

  return true;
};

let motionQuery: MediaQueryList | undefined;

// The provider mirrors its preference onto <html>; the system setting always
// counts, as it does in liquid.css.
export function motionReduced() {
  motionQuery ??= window.matchMedia('(prefers-reduced-motion: reduce)');

  return (
    document.documentElement.getAttribute('data-lg-reduce-motion') === '1' || motionQuery.matches
  );
}

export type FrameLoop = {
  start: () => void;
  stop: () => void;
};

// Calls step once a frame with the seconds since the last one until it
// returns false. A long pause counts as one short frame.
export function createFrameLoop(step: (dt: number) => boolean): FrameLoop {
  let frame = 0;
  let last = 0;

  const tick = (now: number) => {
    const dt = last ? Math.min((now - last) / 1000, 1 / 20) : 1 / 60;

    last = now;
    frame = 0;

    if (step(dt)) {
      frame = requestAnimationFrame(tick);

      return;
    }

    last = 0;
  };

  return {
    start() {
      if (!frame) frame = requestAnimationFrame(tick);
    },
    stop() {
      cancelAnimationFrame(frame);
      frame = 0;
      last = 0;
    },
  };
}

type Edge = 'left' | 'top' | 'right' | 'bottom';

type Box = Record<Edge, number>;

type Feel = readonly [response: number, bounce: number];

const EDGES: readonly Edge[] = ['left', 'top', 'right', 'bottom'];

// The edge heading for the new item leads and the far edge follows, so the
// bubble stretches into a drop on the way and rounds off when it lands. The
// leading edge overshoots a little and rings back, which is what makes the
// landing feel like a drop settling rather than a slide stopping.
const LEAD: Feel = [0.2, 0.32];

const TRAIL: Feel = [0.3, 0.12];

const EVEN: Feel = [0.26, 0.22];

// Under a finger the bubble keeps up closely but still leans into the drag.
const DRAG_LEAD: Feel = [0.1, 0.12];

const DRAG_TRAIL: Feel = [0.18, 0.04];

// How far a lifted bubble grows past its item, in CSS pixels. It never grows
// past the control's own edge. Kept to a hair: more reads as the bubble
// zooming out of its track.
const SWELL = 1;

const DRAG_THRESHOLD = 4;

// The bubble counts as travelling, and stays lifted, while an edge moves faster
// than this in CSS pixels a second, so it settles the moment it slows down.
const TRAVEL_SPEED = 90;

// How far a press on another item wakes the bubble before it moves.
const ANTICIPATION = 0.5;

// Measure before the containing plane is projected. Client rectangles describe the projected
// bounding box, which cannot be scaled back into a rectangle once an ancestor turns in 3D.
export function localRect(element: HTMLElement, root: HTMLElement) {
  const size = (node: HTMLElement, style: CSSStyleDeclaration) => {
    const borderBox = style.boxSizing === 'border-box';
    const width = parseFloat(style.width);
    const height = parseFloat(style.height);

    return {
      width: Number.isFinite(width)
        ? width +
          (borderBox
            ? 0
            : parseFloat(style.paddingLeft) +
              parseFloat(style.paddingRight) +
              parseFloat(style.borderLeftWidth) +
              parseFloat(style.borderRightWidth))
        : node.offsetWidth,
      height: Number.isFinite(height)
        ? height +
          (borderBox
            ? 0
            : parseFloat(style.paddingTop) +
              parseFloat(style.paddingBottom) +
              parseFloat(style.borderTopWidth) +
              parseFloat(style.borderBottomWidth))
        : node.offsetHeight,
    };
  };

  const elementStyle = getComputedStyle(element);
  const dimensions = size(element, elementStyle);
  let matrix = new DOMMatrix();

  for (let node: HTMLElement | null = element; node && node !== root;) {
    const style = node === element ? elementStyle : getComputedStyle(node);
    const parent: Element | null = node.offsetParent;
    const { width, height } = size(node, style);

    const length = (value: string, extent: number) =>
      value.endsWith('%') ? (parseFloat(value) * extent) / 100 : parseFloat(value) || 0;

    const origin = style.transformOrigin.split(' ');
    const translate = style.translate.split(' ');
    const scale = style.scale === 'none' ? [1, 1] : style.scale.split(' ').map(Number);

    const left =
      style.position === 'absolute' && style.left !== 'auto'
        ? parseFloat(style.left)
        : node.offsetLeft;

    const top =
      style.position === 'absolute' && style.top !== 'auto'
        ? parseFloat(style.top)
        : node.offsetTop;

    const borderX =
      parent instanceof HTMLElement && parent !== root ? parent.clientLeft - parent.scrollLeft : 0;

    const borderY =
      parent instanceof HTMLElement && parent !== root ? parent.clientTop - parent.scrollTop : 0;

    const x = length(origin[0], width);
    const y = length(origin[1], height);

    const transform = new DOMMatrix()
      .translate(left + borderX, top + borderY)
      .translate(x, y)
      .translate(length(translate[0], width), length(translate[1] ?? '0', height))
      .scale(scale[0], scale[1] ?? scale[0])
      .multiply(new DOMMatrix(style.transform === 'none' ? undefined : style.transform))
      .translate(-x, -y);

    matrix = transform.multiply(matrix);
    node = parent instanceof HTMLElement ? parent : null;
  }

  const points = [
    [0, 0],
    [dimensions.width, 0],
    [dimensions.width, dimensions.height],
    [0, dimensions.height],
  ].map(([x, y]) => new DOMPoint(x, y).matrixTransform(matrix));

  const left = Math.min(...points.map((point) => point.x));
  const top = Math.min(...points.map((point) => point.y));

  return {
    left,
    top,
    width: Math.max(...points.map((point) => point.x)) - left,
    height: Math.max(...points.map((point) => point.y)) - top,
  };
}

function boxWithin(element: HTMLElement, frame: HTMLElement): Box {
  const { left, top, width, height } = localRect(element, frame);

  return { left, top, right: left + width, bottom: top + height };
}

// Four zero-size points give the browser's actual projection, including perspective. Only a
// drag needs these; the static bubble and glass never need to read projected geometry.
function pointerPlane(element: HTMLElement) {
  const probes = [
    [0, 0],
    [100, 0],
    [100, 100],
    [0, 100],
  ].map(([x, y]) => {
    const probe = document.createElement('span');
    probe.ariaHidden = 'true';
    probe.style.cssText = `position:absolute;left:${x}%;top:${y}%;width:0;height:0;visibility:hidden;pointer-events:none;`;
    element.append(probe);

    return probe;
  });

  return {
    x(clientX: number, clientY: number) {
      const [p0, p1, p2, p3] = probes.map((probe) => probe.getBoundingClientRect());

      const dx1 = p1.x - p2.x,
        dx2 = p3.x - p2.x,
        dx3 = p0.x - p1.x + p2.x - p3.x;

      const dy1 = p1.y - p2.y,
        dy2 = p3.y - p2.y,
        dy3 = p0.y - p1.y + p2.y - p3.y;

      const determinant = dx1 * dy2 - dx2 * dy1;
      const g = (dx3 * dy2 - dx2 * dy3) / determinant;
      const h = (dx1 * dy3 - dx3 * dy1) / determinant;
      const a = p1.x - p0.x + g * p1.x - clientX * g;
      const b = p3.x - p0.x + h * p3.x - clientX * h;
      const d = p1.y - p0.y + g * p1.y - clientY * g;
      const e = p3.y - p0.y + h * p3.y - clientY * h;
      const x = ((clientX - p0.x) * e - b * (clientY - p0.y)) / (a * e - b * d);

      return x * element.clientWidth + element.scrollLeft;
    },
    destroy: () => probes.forEach((probe) => probe.remove()),
  };
}

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

export type LiquidIndicatorOptions = {
  /** Matches the item the bubble sits under. */
  selected: string;
  /** Matches every item the bubble can move to. */
  item: string;
  /** Lets a pointer pick the bubble up and drop it on another item. */
  draggable?: boolean;
  /** Strength of the bubble's stretch and lift. */
  deformation?: number;
};

/**
 * Moves a selection bubble between items like a glass droplet: it
 * lifts, stretches toward the new item and lands with a little bounce.
 * Labels stay fixed while the bubble moves. CSS places the bubble until this
 * runs. Reduced motion jumps instead.
 */
export function useLiquidIndicator(
  rootRef: RefObject<HTMLElement | null>,
  indicatorRef: RefObject<HTMLElement | null>,
  { selected, item, draggable = false, deformation = 1 }: LiquidIndicatorOptions,
) {
  useLayoutEffect(() => {
    const root = rootRef.current;
    const indicator = indicatorRef.current;

    if (!root || !indicator) return;

    const edges: Record<Edge, Spring> = {
      left: createSpring(...EVEN, 0, 0.05),
      top: createSpring(...EVEN, 0, 0.05),
      right: createSpring(...EVEN, 0, 0.05),
      bottom: createSpring(...EVEN, 0, 0.05),
    };

    const lift = createSpring(0.22, 0.2, 0);
    let items: HTMLElement[] = [];
    let centres: number[] = [];
    let room = 0;
    let placed = false;
    let held: Element | null = null;
    let drag: { pointer: number; startX: number; offset: number; active: boolean } | null = null;
    let plane: ReturnType<typeof pointerPlane> | null = null;

    const frameOf = () =>
      indicator.offsetParent instanceof HTMLElement ? indicator.offsetParent : root;

    const paint = () => {
      const width = edges.right.value - edges.left.value;
      const height = edges.bottom.value - edges.top.value;
      const restWidth = Math.max(edges.right.target - edges.left.target, 1);
      const restHeight = Math.max(edges.bottom.target - edges.top.target, 1);
      // A stretched drop keeps its volume, so it thins across its travel.
      const thinY = clamp(1 / Math.sqrt(Math.max(width / restWidth, 1)), 0.8, 1);
      const thinX = clamp(1 / Math.sqrt(Math.max(height / restHeight, 1)), 0.8, 1);
      // A spring that rings past rest must not lift the bubble below its resting size.
      const raised = Math.max(lift.value, 0) * deformation;
      const swell = raised * Math.min(room, SWELL);
      const drawnWidth = restWidth + (width * thinX - restWidth) * deformation + swell * 2;
      const drawnHeight = restHeight + (height * thinY - restHeight) * deformation + swell * 2;
      const centreX = (edges.left.value + edges.right.value) / 2;
      const centreY = (edges.top.value + edges.bottom.value) / 2;

      indicator.style.translate = `${centreX - drawnWidth / 2}px ${centreY - drawnHeight / 2}px`;
      indicator.style.width = `${drawnWidth}px`;
      indicator.style.height = `${drawnHeight}px`;
      indicator.style.setProperty('--lg-lift', raised.toFixed(3));
    };

    const step = (dt: number) => {
      const reduced = motionReduced();
      const travelling = EDGES.some((edge) => Math.abs(edges[edge].velocity) > TRAVEL_SPEED);
      const pressed = held?.matches(selected) ?? false;
      const woken = held !== null ? ANTICIPATION : 0;

      lift.target = reduced ? 0 : pressed || drag?.active || travelling ? 1 : woken;
      let moving = false;

      for (const edge of EDGES) {
        moving = stepSpring(edges[edge], dt, reduced) || moving;
      }

      moving = stepSpring(lift, dt, reduced) || moving;
      paint();

      return moving;
    };

    const loop = createFrameLoop(step);

    const current = (): Box => ({
      left: edges.left.value,
      top: edges.top.value,
      right: edges.right.value,
      bottom: edges.bottom.value,
    });

    // Tunes each axis so the edge in front leads and the one behind trails.
    const lean = (from: Box, to: Box, lead: Feel, trail: Feel) => {
      const axes: [Edge, Edge, number][] = [
        ['left', 'right', (to.left + to.right - from.left - from.right) / 2],
        ['top', 'bottom', (to.top + to.bottom - from.top - from.bottom) / 2],
      ];

      for (const [start, end, distance] of axes) {
        if (Math.abs(distance) < 1) {
          retuneSpring(edges[start], ...EVEN);
          retuneSpring(edges[end], ...EVEN);
        } else {
          retuneSpring(edges[distance > 0 ? end : start], ...lead);
          retuneSpring(edges[distance > 0 ? start : end], ...trail);
        }
      }
    };

    const aim = (to: Box, jump: boolean) => {
      for (const edge of EDGES) {
        edges[edge].target = to[edge];

        if (jump) {
          edges[edge].value = to[edge];
          edges[edge].velocity = 0;
        }
      }
    };

    const sync = (snap: boolean) => {
      const frame = frameOf();
      const target = root.querySelector<HTMLElement>(selected);

      // Only a drag needs every item's centre; ordinary tabs measure their selected item.
      items = draggable
        ? Array.from(root.querySelectorAll<HTMLElement>(item))
        : target
          ? [target]
          : [];

      const boxes = items.map((element) => boxWithin(element, frame));

      centres = boxes.map((box) => (box.left + box.right) / 2);

      // A pointer owns the bubble until it lets go.
      if (drag?.active) return;

      if (!target) {
        indicator.setAttribute('data-lg-empty', '');
        placed = false;

        return;
      }

      const targetIndex = items.indexOf(target);
      const box = targetIndex < 0 ? boxWithin(target, frame) : boxes[targetIndex];
      const jump = snap || !placed || motionReduced();

      indicator.removeAttribute('data-lg-empty');
      room = Math.max(0, Math.min(box.top, frame.clientHeight - box.bottom));

      if (!jump) lean(current(), box, LEAD, TRAIL);

      aim(box, jump);
      placed = true;

      if (jump) paint();

      loop.start();
    };

    const follow = (event: PointerEvent) => {
      if (!drag || !plane || centres.length === 0) return;

      const width = edges.right.target - edges.left.target;

      const centre = clamp(
        plane.x(event.clientX, event.clientY) - drag.offset,
        Math.min(...centres),
        Math.max(...centres),
      );

      const from = current();
      const to = { ...from, left: centre - width / 2, right: centre + width / 2 };

      lean(from, to, DRAG_LEAD, DRAG_TRAIL);
      aim({ ...to, top: edges.top.target, bottom: edges.bottom.target }, motionReduced());
      loop.start();
    };

    // Drops a dragged bubble on the nearest enabled item, or puts it back.
    const release = (commit: boolean) => {
      if (!drag) return;

      const { active, pointer } = drag;

      drag = null;
      plane?.destroy();
      plane = null;
      held = null;
      root.removeAttribute('data-lg-dragging');

      if (root.hasPointerCapture(pointer)) root.releasePointerCapture(pointer);

      if (active && commit) {
        const centre = (edges.left.target + edges.right.target) / 2;
        let nearest = -1;

        centres.forEach((value, index) => {
          if (items[index].matches('[data-disabled]')) return;

          if (nearest < 0 || Math.abs(value - centre) < Math.abs(centres[nearest] - centre))
            nearest = index;
        });

        if (nearest >= 0) {
          if (root.contains(document.activeElement)) items[nearest].focus({ preventScroll: true });

          items[nearest].click();
        }
      }

      sync(false);
    };

    const onPointerDown = (event: PointerEvent) => {
      if (!event.isPrimary || event.button !== 0 || !(event.target instanceof Element)) return;

      const pressed = event.target.closest(item);

      if (
        !(pressed instanceof HTMLElement) ||
        !root.contains(pressed) ||
        pressed.matches('[data-disabled]')
      )
        return;

      held = pressed;
      loop.start();

      if (!draggable || !pressed.matches(selected)) return;

      const centre = (edges.left.target + edges.right.target) / 2;
      plane = pointerPlane(frameOf());

      drag = {
        pointer: event.pointerId,
        startX: event.clientX,
        offset: plane.x(event.clientX, event.clientY) - centre,
        active: false,
      };
    };

    const onPointerMove = (event: PointerEvent) => {
      if (!drag || event.pointerId !== drag.pointer) return;

      if (!drag.active) {
        if (Math.abs(event.clientX - drag.startX) < DRAG_THRESHOLD) return;

        drag.active = true;
        root.setAttribute('data-lg-dragging', '');
        root.setPointerCapture(event.pointerId);
      }

      follow(event);
    };

    // Listens on the window, so a press that ends outside the control still ends.
    const onPointerUp = (event: PointerEvent) => {
      if (drag && event.pointerId === drag.pointer) {
        release(event.type === 'pointerup');

        return;
      }

      if (!held) return;

      held = null;
      loop.start();
    };

    // Taking the pointer from a touched item fires this on the item; only the
    // root losing it ends a drag.
    const onLostCapture = (event: PointerEvent) => {
      if (event.target === root && drag?.active && event.pointerId === drag.pointer) release(false);
    };

    const resizes = new ResizeObserver(() => sync(true));

    const observeSizes = () => {
      resizes.disconnect();
      resizes.observe(root);
      root.querySelectorAll<HTMLElement>(item).forEach((element) => resizes.observe(element));
    };

    const mutations = new MutationObserver((records) => {
      if (records.some((record) => record.type === 'childList')) observeSizes();

      sync(false);
    });

    root.setAttribute('data-lg-indicator', 'ready');
    sync(true);
    observeSizes();
    mutations.observe(root, {
      attributes: true,
      attributeFilter: ['data-state', 'data-disabled'],
      childList: true,
      subtree: true,
    });
    root.addEventListener('pointerdown', onPointerDown);
    root.addEventListener('pointermove', onPointerMove);
    root.addEventListener('lostpointercapture', onLostCapture);
    window.addEventListener('pointerup', onPointerUp);
    window.addEventListener('pointercancel', onPointerUp);

    return () => {
      loop.stop();
      plane?.destroy();
      mutations.disconnect();
      resizes.disconnect();
      root.removeEventListener('pointerdown', onPointerDown);
      root.removeEventListener('pointermove', onPointerMove);
      root.removeEventListener('lostpointercapture', onLostCapture);
      window.removeEventListener('pointerup', onPointerUp);
      window.removeEventListener('pointercancel', onPointerUp);
      root.removeAttribute('data-lg-indicator');
      root.removeAttribute('data-lg-dragging');
      indicator.removeAttribute('data-lg-empty');
      ['translate', 'width', 'height', '--lg-lift'].forEach((property) =>
        indicator.style.removeProperty(property),
      );
    };
  }, [deformation, draggable, indicatorRef, item, rootRef, selected]);
}

@layer components {
  /* A slab of glass floating clear of the page, with its menu outside the
     material's paint clip. Container queries also fit embedded headers. */
  .lg-header {
    position: fixed;
    inset: 14px 0 auto;
    z-index: 40;
    box-sizing: border-box;
    width: min(920px, calc(100vw - 32px));
    height: 56px;
    margin-inline: auto;
    border-radius: 999px;
    color: var(--lg-foreground);
    container-type: inline-size;
  }

  .lg-header[data-position='static'] {
    position: relative;
    inset: auto;
    z-index: auto;
    width: 100%;
    max-width: 920px;
  }

  /* Frosted as lightly as the other slabs, so the page shows through and bends
     at the rim. The --lg-header-* tint and dimming keep the links legible. */
  .lg-header > .lg-header-glass {
    --lg-panel-radius: 999px;
    --lg-glass-blur: calc(var(--lg-slab-blur) * 1px);
    --lg-lens-blur: var(--lg-slab-blur);
    --lg-lens-body-brightness: var(--lg-header-brightness);
    --lg-lens-rim-brightness: var(--lg-header-rim-brightness);
    --lg-glass-contrast: 1;
    --lg-glass-sat: 1.5;
    --lg-glass-brightness: var(--lg-header-brightness);
    --lg-panel-elevation-shadow:
      0 2px 4px -2px rgb(52 62 84 / 0.18), 0 4px 14px -3px rgb(52 62 84 / 0.2);
    position: absolute;
    inset: 0;
    height: 100%;
    pointer-events: none;
  }

  .lg-header > .lg-header-glass::before {
    background-color: var(--lg-header-tint);
  }

  /* A condensing header opens out across the top of the page with no glass and gathers into
     the capsule once the page scrolls. GlassHeader springs --lg-header-spread (1 open, 0 the
     capsule) and --lg-header-material (the glass, 0 to 1) while it moves; at rest its
     data-condensed state sets them. The open bar is never narrower than the capsule, so the
     links stay on one side of the menu breakpoint throughout. */
  .lg-header[data-condense-on-scroll] {
    --lg-header-spread: 1;
    --lg-header-material: 0;
    --lg-header-capsule-width: min(920px, calc(100vw - 32px));
    --lg-header-bar-width: max(var(--lg-header-capsule-width), min(1200px, calc(100% - 48px)));
  }

  .lg-header[data-condensed='true'] {
    --lg-header-spread: 0;
    --lg-header-material: 1;
  }

  .lg-header[data-position='fixed'][data-condense-on-scroll] {
    width: calc(
      var(--lg-header-capsule-width) +
        (var(--lg-header-bar-width) - var(--lg-header-capsule-width)) * var(--lg-header-spread)
    );
  }

  /* Before the script runs, as on a page opened at an anchor, the scroll position alone picks
     the shape: a custom property animates discretely, so it switches halfway, 8px down. */
  @supports (animation-timeline: scroll()) {
    .lg-header[data-condense-on-scroll]:not([data-condensed]) {
      animation: lg-header-condensed linear both;
      animation-timeline: scroll(root);
      animation-range: 0px 16px;
    }
  }

  @keyframes lg-header-condensed {
    to {
      --lg-header-spread: 0;
      --lg-header-material: 1;
    }
  }

  /* The glass fades on its own layers, never on an ancestor: an ancestor's opacity would cut
     the frost off from the page it bends. The spring sets the shadow every frame, so the
     surface's own shadow transition stays out of its way. */
  .lg-header[data-condense-on-scroll] > .lg-header-glass {
    --lg-panel-elevation-shadow:
      0 2px 4px -2px rgb(52 62 84 / calc(0.18 * var(--lg-header-material))),
      0 4px 14px -3px rgb(52 62 84 / calc(0.2 * var(--lg-header-material)));
    transition: none;
  }

  .lg-header[data-condense-on-scroll] > .lg-header-glass::before,
  .lg-header[data-condense-on-scroll] > .lg-header-glass::after {
    opacity: var(--lg-header-material);
  }

  .lg-header[data-condense-on-scroll] > .lg-header-glass > .lg-noise {
    opacity: calc(var(--lg-noise-alpha) * var(--lg-header-material));
  }

  /* The forced-colours outline edges the glass, so it goes with it: the open bar has none.
     Increased contrast edges it with the ring above, which fades with the glass. */
  @media (forced-colors: active) {
    .lg-header[data-condense-on-scroll] > .lg-header-glass {
      outline-width: calc(1px * var(--lg-header-material)) !important;
    }
  }

  /* A small button at the end sits as far from the rim as from the top and bottom, so it nests
     in the capsule's curve, and the brand starts as far in as that button's label. */
  .lg-header-bar {
    position: relative;
    display: flex;
    align-items: center;
    gap: 16px;
    height: 100%;
    padding: 0 12px 0 24px;
  }

  .lg-header-brand {
    flex: none;
    min-width: 0;
    margin-inline-end: auto;
    font-size: 18px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.03em;
    white-space: nowrap;
  }

  .lg-header-brand a {
    color: inherit;
    text-decoration: none;
  }

  .lg-header-links {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 2px;
  }

  .lg-header-desktop {
    margin-inline: auto;
  }

  .lg-header-links a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 38px;
    padding: 0 12px;
    border-radius: 999px;
    color: var(--lg-muted-foreground);
    font-size: 15px;
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.01em;
    text-decoration: none;
    white-space: nowrap;
    transition:
      color var(--lg-motion-duration) ease,
      background-color var(--lg-motion-duration) ease;
  }

  /* Colour alone marks hover and the current page in the bar: a fill would lay a pale patch
     over the glass and whatever the page shows through it. The opaque menu keeps its fill. */
  .lg-header-links a:hover,
  .lg-header-links a[aria-current='page'] {
    color: var(--lg-foreground);
  }

  .lg-header :is(a, summary):focus-visible {
    outline: 2px solid var(--lg-focus-ring);
    outline-offset: 2px;
  }

  .lg-header-actions {
    display: flex;
    flex: none;
    align-items: center;
    gap: 4px;
  }

  .lg-header-menu {
    display: none;
  }

  .lg-header-menu summary {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 40px;
    padding: 0 12px;
    border-radius: 999px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    list-style: none;
    user-select: none;
  }

  .lg-header-menu summary::-webkit-details-marker {
    display: none;
  }

  .lg-header-menu-links {
    position: absolute;
    top: calc(100% + 8px);
    right: 10px;
    z-index: 1;
    flex-direction: column;
    align-items: stretch;
    box-sizing: border-box;
    width: min(240px, calc(100cqw - 20px));
    max-height: calc(100dvh - 96px);
    overflow-y: auto;
    padding: 8px;
    border: 1px solid var(--lg-border);
    border-radius: 20px;
    background: var(--lg-opaque-surface);
    box-shadow: var(--lg-shadow-raised);
  }

  .lg-header-menu-links a {
    justify-content: flex-start;
    height: 44px;
    padding: 0 16px;
    border-radius: 12px;
  }

  .lg-header-menu-links a:hover,
  .lg-header-menu-links a[aria-current='page'] {
    background: var(--lg-control-surface);
  }

  .lg-header-menu:not([open]) > nav {
    display: none;
  }

  @container (max-width: 780px) {
    .lg-header-bar {
      gap: 8px;
    }

    .lg-header-desktop {
      display: none;
    }

    .lg-header-menu {
      display: block;
    }
  }

  /* The narrowest phones close up the items and the margins, so the bar still fits and an icon
     button at the end still nests in the curve. */
  @container (max-width: 320px) {
    .lg-header-bar {
      gap: 4px;
      padding: 0 10px 0 20px;
    }
  }

  @media (max-width: 700px) {
    .lg-header[data-position='fixed'] {
      top: 8px;
      width: calc(100vw - 20px);
    }

    /* On a phone the open bar reaches the screen's edges and the capsule draws in from them. */
    .lg-header[data-condense-on-scroll] {
      --lg-header-capsule-width: calc(100vw - 20px);
      --lg-header-bar-width: 100%;
    }
  }
}

