  'Breathing sessions from one minute to twenty',
  'Downloads for nights without signal',
  'Up to five people in one household',
];

/** A price that counts to its new value when the billing period changes. */
function useCountedPrice(target: number) {
  const [shown, setShown] = useState(target);
  const shownRef = useRef(target);

  useEffect(() => {
    const from = shownRef.current;

    if (from === target) return;

    const start = performance.now();
    let frame = requestAnimationFrame(tick);

    function tick(now: number) {
      const progress = motionReduced() ? 1 : Math.min(1, (now - start) / 620);
      const value = progress === 1 ? target : from + (target - from) * (1 - (1 - progress) ** 3);

      shownRef.current = value;
      setShown(value);

      if (progress < 1) frame = requestAnimationFrame(tick);
    }

    return () => cancelAnimationFrame(frame);
  }, [target]);

  return shown;
}

export function PricingPlan({
  storeLinks,
  onDemo,
}: {
  storeLinks?: StoreLinks;
  onDemo: (platform: StorePlatform) => void;
}) {
  const [period, setPeriod] = useState<Period>('yearly');
  const plan = PLANS[period];
  const price = useCountedPrice(plan.price);

  return (
    <GlassPanel
      aria-labelledby="still-plan-title"
      className="still-plan still-pane still-rise"
      lens
      role="group"
      variant="card"
    >
      <div className="still-plan-top">
        <h3 id="still-plan-title">Everything in Still</h3>
        <GlassSegmentedControl
          aria-label="Billing period"
          className="still-period"
          value={period}
          onValueChange={(value) => setPeriod(value === 'monthly' ? 'monthly' : 'yearly')}
        >
          <GlassSegmentedControlItem value="yearly">Yearly</GlassSegmentedControlItem>
          <GlassSegmentedControlItem value="monthly">Monthly</GlassSegmentedControlItem>
        </GlassSegmentedControl>
      </div>
      <div aria-live="polite">
        <p className="still-price">
          <span className="still-price-figure">
            <span aria-hidden>${price.toFixed(2)}</span>
            <span className="still-sr-only">${plan.price.toFixed(2)}</span>
          </span>
          <span className="still-price-per">{plan.per}</span>
        </p>
        <p className="still-price-note">{plan.note}</p>
      </div>
      <ul className="still-plan-list">
        {INCLUDED.map((item) => (
          <li key={item}>
            <CheckIcon />
            {item}
          </li>
        ))}
      </ul>
      <div className="still-plan-action">
        <StoreMenu links={storeLinks} onDemo={onDemo} />
      </div>
      <p className="still-plan-fine">We’ll remind you two days before the week ends.</p>
    </GlassPanel>
  );
}

'use client';

import { GlassButton } from '../../glass-button';
import { GlassMenu, GlassMenuContent, GlassMenuItem, GlassMenuTrigger } from '../../glass-menu';
import { DownIcon, HandsetIcon, PhoneIcon } from './icons';

export type StorePlatform = 'iphone' | 'android';

/** Your app's store pages. A platform without one shows a demo note instead of leaving the page. */
export type StoreLinks = Partial<Record<StorePlatform, string>>;

// Spread rather than written as an attribute, as the library does: the shadcn CLI rewrites a
// literal asChild into a render prop for some styles, which these Radix parts do not take.
export const slotProps = { asChild: true };

const STORES = [
  { platform: 'iphone', name: 'For iPhone', detail: 'iOS 17 and later', Glyph: PhoneIcon },
  { platform: 'android', name: 'For Android', detail: 'Android 10 and later', Glyph: HandsetIcon },
] as const;

/** Its menu draws the stores with Still's own glyphs rather than any store's badge. */
export function StoreMenu({
  label = 'Start your free week',
  links,
  onDemo,
}: {
  label?: string;
  links?: StoreLinks;
  onDemo: (platform: StorePlatform) => void;
}) {
  return (
    <GlassMenu>
      <GlassMenuTrigger {...slotProps}>
        <GlassButton className="still-button-xl still-store-trigger" variant="prominent">
          {label}
          <DownIcon />
        </GlassButton>
      </GlassMenuTrigger>
      <GlassMenuContent
        aria-label="Choose your phone"
        className="still still-store-menu"
        data-lg-theme="dark"
      >
        {STORES.map(({ platform, name, detail, Glyph }) => {
          const href = links?.[platform];

          const body = (
            <>
              <Glyph />
              <span>
                <b>{name}</b>
                <small>{detail}</small>
              </span>
            </>
          );

          return href ? (
            <GlassMenuItem key={platform} {...slotProps} className="still-store-item">
              <a href={href}>{body}</a>
            </GlassMenuItem>
          ) : (
            <GlassMenuItem
              key={platform}
              className="still-store-item"
              onSelect={() => onDemo(platform)}
            >
              {body}
            </GlassMenuItem>
          );
        })}
      </GlassMenuContent>
    </GlassMenu>
  );
}

