/*
  Still, a Glassy UI template. Every rule is scoped to .still. Set --still-accent,
  --still-accent-rotate, --still-accent-ink, --still-serif and --still-sans on any ancestor to
  change the accent and the fonts.
*/

.still {
  --st-accent: var(--still-accent, #e6dcff);
  --st-accent-ink: var(--still-accent-ink, #1d1638);
  --st-serif: var(--still-serif, 'Iowan Old Style', Georgia, 'Times New Roman', serif);
  --st-sans: var(
    --still-sans,
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    system-ui,
    sans-serif
  );
  --st-night: #17142a;
  --st-ink: #f3eefb;
  --st-ink-2: #c3b9d6;
  --st-ink-3: #a99fc0;
  --st-line: rgb(230 220 255 / 0.14);
  --st-wrap: 1200px;
  --st-pad: clamp(20px, 4vw, 40px);
  --st-section: clamp(80px, 7.5vw, 120px);
  --st-ease-in: cubic-bezier(0.5, 0, 0.75, 0);

  /* The library's tokens, in Still's night and lavender. */
  --lg-foreground: var(--st-ink);
  --lg-muted-foreground: var(--st-ink-2);
  --lg-accent: var(--st-accent);
  --lg-accent-foreground: var(--st-accent-ink);
  --lg-prominent-fill: var(--st-accent);
  /* Recolours whatever sits behind a prominent button into a pale lavender, so its dark label
     keeps 11:1 over the dusk. */
  --lg-prominent-tint: grayscale(1) contrast(0.15) brightness(1.35) sepia(1)
    hue-rotate(var(--still-accent-rotate, 210deg)) saturate(0.9) brightness(1.2);
  --lg-prominent-glow: 248 244 255;
  --lg-prominent-shade: 29 22 56;
  --lg-switch-on: #8b78c9;
  --lg-focus-ring: var(--st-accent);
  --lg-control-surface: rgb(16 12 34 / 0.5);
  --lg-control-surface-hover: rgb(16 12 34 / 0.66);
  --lg-border: rgb(230 220 255 / 0.14);
  --lg-overlay-surface: rgb(33 27 58 / 0.86);
  --lg-opaque-surface: #231d3c;
  --lg-header-tint: rgb(49 39 100 / 0.5);
  --lg-track: rgb(255 255 255 / 0.12);

  color: var(--st-ink);
  font-family: var(--st-sans);
  letter-spacing: normal;
}

@layer base {
  .still :where(h1, h2, h3, p, ul, blockquote, figure) {
    margin: 0;
    padding: 0;
  }

  .still :where(ul) {
    list-style: none;
  }

  .still :where(a) {
    color: inherit;
  }

  .still :where(h1, h2, h3) {
    font-family: var(--st-serif);
    font-weight: 500;
    letter-spacing: -0.01em;
    text-wrap: balance;
  }

  .still :where(p) {
    text-wrap: pretty;
  }
}

html:has(.still-page) {
  background: #17142a;
  scroll-padding-top: 92px;
}

@media (prefers-reduced-motion: no-preference) {
  html:has(.still-page) {
    scroll-behavior: smooth;
  }
}

/* One evening down the page: dusk plum deepens to night. */
.still-page {
  position: relative;
  min-height: 100vh;
  min-width: 320px;
  overflow-x: clip;
  background: linear-gradient(
    180deg,
    #17142a 0%,
    #1a1631 16%,
    #1f1737 32%,
    #231939 46%,
    #1e1636 60%,
    #18142f 76%,
    #17142a 100%
  );
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.still-icon {
  display: block;
  width: 20px;
  height: 20px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.still-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.still :where(a, [tabindex]:not([tabindex='-1'])):focus-visible {
  outline: 2px solid var(--st-accent);
  outline-offset: 3px;
  border-radius: 6px;
}

.still [tabindex='-1']:focus {
  outline: none;
}

.still-skip {
  position: fixed;
  z-index: 100;
  top: 16px;
  left: 16px;
  padding: 10px 16px;
  border-radius: 999px;
  background: var(--st-accent);
  color: var(--st-accent-ink);
  font-weight: 600;
  text-decoration: none;
  transform: translateY(-160%);
  transition: transform 200ms var(--lg-ease-out);
}

.still-skip:focus {
  transform: none;
}

.still-wrap {
  width: min(100% - 2 * var(--st-pad), var(--st-wrap));
  margin-inline: auto;
}

.still-section {
  position: relative;
  padding-block: var(--st-section);
}

.still-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 20px;
  color: var(--st-accent);
  font: 600 13px/1.2 var(--st-sans);
  letter-spacing: 0.06em;
}

.still-eyebrow::before {
  content: '';
  width: 20px;
  height: 1px;
  background: currentColor;
  opacity: 0.6;
}

.still-h2 {
  font-size: clamp(38px, 3vw + 14px, 60px);
  line-height: 1.03;
  letter-spacing: -0.015em;
}

.still-lede {
  max-width: 52ch;
  margin-top: 20px;
  color: var(--st-ink-2);
  font-size: clamp(17px, 0.25vw + 15.5px, 19px);
}

.still-lede a {
  text-decoration: underline;
  text-decoration-color: color-mix(in srgb, var(--st-accent) 45%, transparent);
  text-underline-offset: 3px;
}

/* Panes take the night's plum into their frost, as the page's own glass. */
.still-pane::before {
  background-color: rgb(42 34 72 / 0.3);
}

/* Buttons: the library's slabs at Still's sizes. */
.still-button-sm {
  min-height: 32px;
  padding: 0 15px;
  font-size: 14px;
  font-weight: 600;
}

.still-button {
  min-height: 44px;
  padding: 0 20px;
  font-size: 15px;
  font-weight: 600;
}

.still-button-xl {
  min-height: 56px;
  padding: 0 26px;
  font-size: 17px;
  font-weight: 600;
}

/* The secondary slabs take a little of the lavender into their glass. */
.still .lg-button:not(.lg-button--prominent, .lg-accordion-trigger) {
  --lg-button-fill: rgb(230 220 255 / 0.05);
  --lg-button-fill-hover: rgb(230 220 255 / 0.1);
}

.still .lg-button .lg-button__label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

/* A prominent button's glass recolours the page behind it. In Safari and Firefox the glass may
   see little or none of the page, so its face would show only the dark light under it, behind a
   dark label. There it takes the solid fill instead, as the library does where glass cannot be
   drawn. */
@supports not (-webkit-app-region: drag) {
  .still .lg-button--prominent > .lg-button__layers > .lg-button__distortion {
    background-color: var(--lg-prominent-fill);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

