@container (max-width: 780px) {
  .still-header-cta {
    display: none;
  }
}

@media (max-width: 859px) {
  .still-header.lg-header {
    top: 12px;
    width: calc(100vw - 24px);
    height: 56px;
  }

  .still-header .lg-header-bar {
    padding-left: 14px;
  }
}

/* Hero */
.still-hero {
  --nav-h: 92px;
  --orb: min(72vw, 34svh, 360px);
  --gap: calc(var(--orb) * 0.09);
  --hero-top: calc(var(--nav-h) + clamp(0px, (100svh - 860px) * 0.35, 120px));
  --horizon: calc(var(--hero-top) + var(--gap) + var(--orb) * 0.72);
  position: relative;
  min-height: 100svh;
  padding-bottom: 48px;
  overflow: clip;
}

.still-sky {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

.still-sky > * {
  position: absolute;
  left: 0;
  right: 0;
}

.still-sky-gradient {
  top: 0;
  height: var(--horizon);
  background: linear-gradient(
    180deg,
    #17142a 0%,
    #1b1734 26%,
    #281e44 50%,
    #43295a 70%,
    #6e3d62 86%,
    #a3627c 97%,
    #c0798e 100%
  );
}

.still-sky-stars {
  top: 0;
  width: 100%;
  height: calc(var(--horizon) - 30px);
  fill: #f6f1ff;
}

.still-sky-water {
  top: var(--horizon);
  bottom: 0;
  background: linear-gradient(
    180deg,
    #47294f 0%,
    #2c1d40 9%,
    #211936 30%,
    #1a1631 60%,
    #17142a 100%
  );
}

/* The moon path: a soft column with fine glints in perspective, for the orb to bend. */
.still-sky-path {
  top: var(--horizon);
  width: calc(var(--orb) * 0.9);
  height: 300px;
  margin-inline: auto;
  background: radial-gradient(
    30% 100% at 50% 0%,
    rgb(255 206 222 / 0.3),
    rgb(255 186 210 / 0.1) 42%,
    transparent 78%
  );
}

.still-sky-glints {
  top: calc(var(--horizon) + 1px);
  width: calc(var(--orb) * 0.7);
  height: 240px;
  margin-inline: auto;
  fill: #ffe2ec;
  -webkit-mask-image: linear-gradient(
    180deg,
    #000 calc(var(--orb) * 0.2),
    transparent calc(var(--orb) * 0.27)
  );
  mask-image: linear-gradient(
    180deg,
    #000 calc(var(--orb) * 0.2),
    transparent calc(var(--orb) * 0.27)
  );
}

.still-sky-land {
  fill: #57304f;
}

.still-sky-land--west {
  top: calc(var(--horizon) - 13px);
  right: auto;
  width: max(0px, 50% - var(--orb) * 0.6);
  height: 14px;
}

.still-sky-land--east {
  top: calc(var(--horizon) - 6px);
  left: calc(50% + var(--orb) * 0.58);
  right: auto;
  width: calc(var(--orb) * 0.8);
  height: 7px;
}

.still-sky-venus {
  top: calc(var(--horizon) - var(--orb) * 0.46);
  left: calc(50% - var(--orb) * 1.16);
  right: auto;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #fff6fa;
  box-shadow:
    0 0 6px 1px rgb(255 226 238 / 0.7),
    0 0 18px 4px rgb(255 190 214 / 0.18);
}

.still-sky-glow {
  top: calc(var(--horizon) - 230px);
  width: min(1240px, 100%);
  height: 460px;
  margin-inline: auto;
  background: radial-gradient(
    50% 50% at 50% 50%,
    rgb(255 176 196 / 0.42),
    rgb(200 118 160 / 0.16) 46%,
    transparent 72%
  );
  transform-origin: 50% 50%;
}

.still-sky-horizon {
  top: calc(var(--horizon) - 4px);
  height: 9px;
  background:
    linear-gradient(
        90deg,
        transparent,
        rgb(255 214 228 / 0.3) 18%,
        rgb(255 230 238 / 0.85) 50%,
        rgb(255 214 228 / 0.3) 82%,
        transparent
      )
      50% 50% / 100% 1px no-repeat,
    radial-gradient(50% 50% at 50% 50%, rgb(255 200 220 / 0.28), transparent);
}

/* BreathGuide */
.still-breath {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(100% - 2 * var(--st-pad), 980px);
  margin-inline: auto;
  padding-top: var(--hero-top);
  text-align: center;
}

.still-breath-stage {
  position: relative;
  display: grid;
  place-items: center;
  width: calc(var(--orb) + 2 * var(--gap));
  aspect-ratio: 1;
}

.still-breath-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  fill: none;
}

.still-breath-track {
  stroke: rgb(230 220 255 / 0.18);
  stroke-width: 0.6;
}

.still-breath-trace {
  opacity: 0;
  stroke: var(--st-accent);
  stroke-width: 1;
  stroke-linecap: round;
  stroke-dasharray: 0 1;
  transition: opacity 700ms var(--st-ease-in);
}

.still-breath:is([data-state='running'], [data-state='done']) .still-breath-trace {
  opacity: 1;
  transition: none;
}

.still-breath[data-state='done'] .still-breath-trace {
  stroke-width: 1.4;
  transition: stroke-width 900ms var(--lg-ease-out);
}

.still-breath-tick {
  r: 1.5px;
  fill: rgb(230 220 255 / 0.55);
  transition:
    r 500ms var(--lg-spring),
    fill 400ms var(--lg-ease-out);
}

.still-breath[data-phase='0'] .still-breath-tick--in,
.still-breath[data-phase='1'] .still-breath-tick--hold,
.still-breath[data-phase='2'] .still-breath-tick--out {
  r: 2.6px;
  fill: #fff;
}

.still-breath-bead {
  opacity: 0;
  fill: #fff;
  filter: drop-shadow(0 0 3px rgb(230 220 255 / 0.95));
  transition: opacity 400ms var(--lg-ease-out);
}

.still-breath[data-state='running'] .still-breath-bead {
  opacity: 1;
}

.still-breath-rise {
  position: relative;
  width: var(--orb);
  aspect-ratio: 1;
}

/* The orb is a dome of glass: a lens as deep as it is round, which lifts the horizon behind it
   into an arc and splits it at the rim. */
.still-breath-orb.lg-glass-surface {
  --lg-panel-radius: 50%;
  --lg-glass-blur: 3px;
  --lg-glass-sat: 1.4;
  --lg-lens-bevel: 9999;
  --lg-lens-thickness: 150;
  --lg-lens-blur: 0.5;
  --lg-lens-saturation: 1.4;
  --lg-lens-dispersion: 0.06;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 10px;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  transform-origin: 50% 50%;
  will-change: transform;
}

.still-breath-orb::before {
  background-color: rgb(72 54 116 / 0.08);
}

.still-breath:not([data-state='running']) .still-breath-orb {
  transition: transform 1400ms var(--lg-ease-out);
}

.still-breath-shine {
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: 50%;
  pointer-events: none;
  background:
    radial-gradient(9% 4.5% at 33% 15%, rgb(255 255 255 / 0.5), transparent 76%),
    radial-gradient(38% 22% at 36% 19%, rgb(255 255 255 / 0.07), transparent 72%),
    radial-gradient(72% 36% at 50% 100%, rgb(255 196 214 / 0.22), transparent 72%),
    radial-gradient(
      closest-side,
      transparent 78%,
      rgb(28 16 50 / 0.26) 97%,
      rgb(28 16 50 / 0.08) 100%
    );
}

.still-breath-words {
  position: relative;
  z-index: 3;
  min-height: 1em;
  padding: 0 12%;
  color: #fdfbff;
  font: italic 500 clamp(27px, 1.6vw + 14px, 38px) / 1.05 var(--st-serif);
  text-shadow: 0 1px 14px rgb(23 20 42 / 0.55);
}

.still-breath[data-state='done'] .still-breath-words {
  font-size: clamp(22px, 1vw + 14px, 30px);
  text-wrap: balance;
}

.still-breath-count {
  position: relative;
  z-index: 3;
  min-height: 1em;
  color: var(--st-ink-2);
  font: 600 13px/1 var(--st-sans);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.08em;
}

.still-hero-title {
  margin-top: clamp(18px, 2.6vh, 30px);
  font-size: clamp(46px, 4.6vw + 14px, 80px);
  line-height: 1.02;
  letter-spacing: -0.015em;
  transition:
    opacity 900ms var(--lg-ease-out),
    filter 900ms var(--lg-ease-out);
}

.still-hero-line {
  display: block;
}

.still-hero-line--soft {
  color: var(--st-ink-3);
  font-style: italic;
}

.still-hero-lede {
  max-width: 42ch;
  margin-top: 14px;
  color: var(--st-ink-2);
  font-size: clamp(16px, 0.3vw + 15px, 18px);
  transition:
    opacity 900ms var(--lg-ease-out),
    filter 900ms var(--lg-ease-out);
}

/* While you breathe, the words around the orb step back; they hold no glass. */
.still[data-breathing] :is(.still-hero-title, .still-hero-lede) {
  opacity: 0.18;
  filter: blur(3px);
  transition-duration: 1600ms;
}

.still-breath-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  min-height: 56px;
  margin-top: 26px;
}

.still-breath-status {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 24px;
  margin-top: 14px;
  color: var(--st-ink-2);
  font-size: 14px;
}

.still-breath-escape {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.still-breath-escape .lg-kbd {
  color: var(--st-ink);
}

@media (hover: none) and (pointer: coarse) {
  .still-breath-escape {
    display: none;
  }
}

/* The practice */
.still-practice {
  padding-top: clamp(48px, 5vw, 80px);
}

.still-practice-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  align-items: end;
  column-gap: 24px;
  row-gap: 32px;
}

.still-practice-head {
  grid-column: 1 / span 6;
}

.still-practice-body {
  grid-column: 8 / span 5;
  color: var(--st-ink-2);
  font-size: 18px;
}

.still-curve {
  grid-column: 1 / -1;
  margin-top: 72px;
  view-timeline-name: --still-curve;
}

.still-curve-art {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

.still-curve-area {
  fill: url(#still-curve-fill);
}

.still-curve-line {
  fill: none;
  stroke: var(--st-accent);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 1 1;
  stroke-dashoffset: 0;
}

.still-curve-guide {
  stroke: rgb(230 220 255 / 0.22);
  stroke-width: 1.5;
  stroke-dasharray: 4 8;
}

.still-curve-base {
  stroke: rgb(230 220 255 / 0.16);
  stroke-width: 1.5;
}

.still-curve-dot {
  fill: #17142a;
  stroke: var(--st-accent);
  stroke-width: 3;
}

.still-curve-labels {
  display: grid;
  grid-template-columns: 4fr 2fr 6fr;
  margin-top: 18px;
}

.still-curve-labels p {
  display: grid;
  gap: 2px;
  padding-left: 14px;
  border-left: 1px solid var(--st-line);
}

.still-curve-labels b {
  font: italic 500 24px/1.1 var(--st-serif);
}

.still-curve-labels span {
  color: var(--st-ink-2);
  font-size: 14px;
}

.still-curve figcaption {
  margin-top: 28px;
  color: var(--st-ink-2);
  font-size: 15px;
}

.still-facts {
  display: grid;
  grid-column: 1 / -1;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  margin-top: 88px;
}

.still-fact {
  padding-top: 24px;
  border-top: 1px solid var(--st-line);
}

.still-fact h3 {
  font-size: 44px;
  line-height: 1;
}

.still-fact p {
  max-width: 32ch;
  margin-top: 12px;
  color: var(--st-ink-2);
}

/* Sound scenes */
.still-sounds::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(60% 36% at 12% 30%, rgb(196 120 160 / 0.1), transparent 70%),
    radial-gradient(50% 34% at 88% 62%, rgb(140 120 230 / 0.08), transparent 70%);
}

.still-scenes {
  position: relative;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  margin-top: 64px;
}

/* The art is drawn 1:1 in px, so each scene's brightest line crosses the pane's top rim. */
.still-scene {
  --scene-art: 184px;
  position: relative;
  isolation: isolate;
  display: grid;
  align-content: end;
  padding: var(--scene-art) 12px 12px;
  overflow: hidden;
  border-radius: 32px;
  background: #221b3e;
  box-shadow:
    0 30px 60px -36px rgb(6 2 18 / 0.9),
    inset 0 0 0 1px rgb(255 255 255 / 0.06);
}

.still-scene-art {
  position: absolute;
  inset: 0;
}

.still-scene-art svg {
  display: block;
  width: 100%;
  height: max(520px, 100%);
}

.still-scene-body.lg-glass-surface {
  --lg-panel-radius: 24px;
  display: grid;
  gap: 14px;
  padding: 22px 22px 18px;
}

.still-scene-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.still-scene-title {
  font-size: 31px;
  line-height: 1.05;
}

.still-scene-description {
  color: var(--st-ink-2);
  font-size: 15px;
  line-height: 1.55;
}

.still-scene-wave {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 52px;
  margin-block: 2px;
}

.still-scene-bar {
  flex: 1;
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(180deg, rgb(236 228 255 / 0.95), rgb(206 190 255 / 0.55));
  opacity: 0.62;
  transform-origin: 50% 50%;
  transition:
    transform 700ms var(--lg-ease-out),
    opacity 500ms var(--lg-ease-out);
}

.still-scene[data-playing='true'] .still-scene-bar {
  opacity: 1;
  transition: opacity 400ms var(--lg-ease-out);
}

.still-scene-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.still-scene-toggle {
  min-width: 112px;
}

/* The scene and story buttons draw no lens, to keep each viewport's lenses in budget. Their frost
   stays neutral instead of saturating the violet behind them. */
.still .lg-button:is(.still-scene-toggle, .still-carousel-button) {
  --lg-button-fill: rgb(255 255 255 / 0.08);
  --lg-button-fill-hover: rgb(255 255 255 / 0.12);
  --lg-glass-sat: 1.3;
}

.still-scene-toggle .still-icon {
  width: 18px;
  height: 18px;
}

.still-scene-time {
  color: var(--st-ink-2);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.still-scene-time time {
  color: var(--st-ink);
}

.still-scene-move,
.still-scene-grass {
  animation-play-state: paused;
}

.still-scene-grass {
  transform-box: fill-box;
  transform-origin: 50% 100%;
}

@keyframes still-rain-near {
  to {
    transform: translate(-40px, 220px);
  }
}

@keyframes still-rain-far {
  to {
    transform: translate(-30px, 165px);
  }
}

@keyframes still-train-pass {
  to {
    transform: translateX(-46px);
  }
}

@keyframes still-wind-drift {
  to {
    transform: translateX(-190px);
  }
}

@keyframes still-wind-sway {
  from {
    transform: skewX(-5deg);
  }

  to {
    transform: skewX(4deg);
  }
}

@media (prefers-reduced-motion: no-preference) {
  :root:not([data-lg-reduce-motion='1']) .still-scene-move--rain-near {
    animation: still-rain-near 0.75s linear infinite paused;
  }

  :root:not([data-lg-reduce-motion='1']) .still-scene-move--rain-far {
    animation: still-rain-far 1.5s linear infinite paused;
  }

  :root:not([data-lg-reduce-motion='1']) .still-scene-move--train {
    animation: still-train-pass 0.9s linear infinite paused;
  }

  :root:not([data-lg-reduce-motion='1']) .still-scene-move--wind {
    animation: still-wind-drift 7s linear infinite paused;
  }

  :root:not([data-lg-reduce-motion='1']) .still-scene-grass {
    animation: still-wind-sway 2.6s ease-in-out infinite alternate paused;
  }

  .still-scene[data-playing='true'] :is(.still-scene-move, .still-scene-grass) {
    animation-play-state: running;
  }

  .still-sounds[data-away]
    .still-scene[data-playing='true']
    :is(.still-scene-move, .still-scene-grass) {
    animation-play-state: paused;
  }
}

/* Sleep stories */
.still-carousel-bar {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 32px;
}

.still-carousel-controls {
  display: flex;
  flex: none;
  align-items: center;
  gap: 10px;
}

.still-carousel-button.still-button {
  width: 44px;
  padding: 0;
}

.still-carousel-button[aria-disabled='true'] {
  color: rgb(243 238 251 / 0.34);
  cursor: default;
}

.still-carousel-count {
  min-width: 10ch;
  color: var(--st-ink-2);
  font-size: 14px;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  text-align: center;
}

.still-carousel-track {
  --edge: max(var(--st-pad), calc((100% - var(--st-wrap)) / 2));
  display: grid;
  grid-auto-columns: clamp(244px, 20vw + 12px, 300px);
  grid-auto-flow: column;
  gap: 20px;
  margin: 48px 0 0;
  padding: 8px var(--edge) 28px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-padding-inline: var(--edge);
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}

.still-carousel-track::-webkit-scrollbar {
  display: none;
}

.still .still-carousel-track:focus-visible {
  border-radius: 36px;
  outline-offset: -4px;
}

.still-carousel-item {
  scroll-snap-align: start;
}

.still-story {
  position: relative;
  isolation: isolate;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  border-radius: 28px;
  background: #241c40;
  box-shadow:
    0 26px 50px -30px rgb(6 2 18 / 0.9),
    inset 0 0 0 1px rgb(255 255 255 / 0.06);
  transition: transform 500ms var(--lg-ease-out);
}

.still-story:hover {
  transform: translateY(-4px);
}

.still-story-art {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

.still-story-meta.lg-glass-surface {
  --lg-panel-radius: 20px;
  position: absolute;
  left: 10px;
  right: 10px;
  bottom: 10px;
  display: grid;
  gap: 6px;
  padding: 14px 16px 15px;
}

.still-story-chips {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 2px;
  color: var(--st-ink-2);
  font-size: 13px;
}

.still-story h3 {
  font-size: 23px;
  line-height: 1.1;
}

.still-story p {
  color: var(--st-ink-2);
  font-size: 14px;
}

/* Badges: a pale chip of frost that lifts the lavender of the glass under it. */
.still .lg-badge,
.still-toast .lg-badge {
  --lg-badge-ink: var(--st-ink);
  --lg-glass-sat: 1.6;
  --lg-glass-contrast: 1;
  height: 28px;
  padding: 0 12px;
  background: rgb(255 255 255 / 0.08);
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 0.12),
    inset 0 1px 0 rgb(255 255 255 / 0.16);
  font-family: var(--st-sans);
  font-size: 13px;
}

/* Evenings */
.still-evenings-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  align-items: center;
  column-gap: 24px;
  row-gap: 64px;
}

.still-evenings-copy {
  grid-column: 1 / span 5;
}

.still-evenings-phone {
  position: relative;
  display: grid;
  grid-column: 7 / span 6;
  place-items: center;
}

.still-evenings-phone::before {
  content: '';
  position: absolute;
  width: min(620px, 100%);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(
    closest-side,
    rgb(214 128 160 / 0.26),
    rgb(140 110 220 / 0.1) 55%,
    transparent
  );
  pointer-events: none;
}

.still-points {
  display: grid;
  gap: 28px;
  margin-top: 44px;
}

.still-point {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 18px;
}

.still-point-icon {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: rgb(230 220 255 / 0.07);
  box-shadow: inset 0 0 0 1px rgb(230 220 255 / 0.12);
  color: var(--st-accent);
}

.still-point h3 {
  font: 600 17px/1.35 var(--st-sans);
  letter-spacing: 0;
}

.still-point p {
  margin-top: 4px;
  color: var(--st-ink-2);
  font-size: 16px;
}

/* The phone: an unbranded frame around a live screen laid out in container units. */
.still-phone {
  --w: clamp(270px, 22vw + 20px, 330px);
  position: relative;
  width: var(--w);
  margin: 0;
}

.still-phone-body {
  position: relative;
  aspect-ratio: 402 / 874;
  padding: calc(var(--w) * 0.034);
  border-radius: calc(var(--w) * 0.16);
  background: linear-gradient(150deg, #4a4262, #1a1624 34%, #231d33 66%, #514868);
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 0.14),
    inset 0 0 0 3px #0d0a15,
    0 50px 90px -40px rgb(6 2 18 / 0.95),
    0 0 0 1px rgb(0 0 0 / 0.35);
}

.still-phone-body::before,
.still-phone-body::after {
  content: '';
  position: absolute;
  width: 3px;
  border-radius: 3px;
  background: #3a3350;
}

.still-phone-body::before {
  top: 22%;
  left: -2px;
  height: 9%;
  box-shadow: 0 calc(var(--w) * 0.24) 0 #3a3350;
}

.still-phone-body::after {
  top: 28%;
  right: -2px;
  height: 14%;
}

.still-phone-screen {
  position: relative;
  height: 100%;
  overflow: hidden;
  border-radius: calc(var(--w) * 0.128);
  background: #1a1530;
  color: var(--st-ink);
  container-type: inline-size;
}

.still-phone-wall {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(56cqw 40cqw at 76% 17%, rgb(236 222 255 / 0.32), transparent 70%),
    radial-gradient(12cqw 64cqw at 74% 61.5%, rgb(255 206 222 / 0.3), transparent 72%),
    radial-gradient(100cqw 34cqw at 50% 61%, rgb(255 160 186 / 0.4), transparent 70%),
    linear-gradient(
      180deg,
      #19152f 0%,
      #2a2048 30%,
      #563262 52%,
      #a0607a 61%,
      #3d2549 61.4%,
      #261b3c 74%,
      #18142c 100%
    );
}

.still-phone-wall svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 62%;
  fill: #f6f1ff;
}

.still-phone-wall .still-phone-glints {
  top: 61.8%;
  height: 36%;
  fill: #ffe2ec;
}

.still-phone-wall::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 61.2%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(255 226 236 / 0.8), transparent);
}

.still-phone-warm {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgb(255 150 70 / 0.06), rgb(150 60 20 / 0.24));
  opacity: 0;
  pointer-events: none;
  transition: opacity 900ms var(--lg-ease-out);
}

.still-phone-screen[data-warm] .still-phone-warm {
  opacity: 1;
}

.still-phone-island {
  position: absolute;
  z-index: 3;
  top: 3.2cqw;
  left: 35cqw;
  width: 30cqw;
  height: 8.8cqw;
  border-radius: 99px;
  background: #06040b;
}

.still-phone-status {
  position: absolute;
  z-index: 2;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 15cqw;
  padding: 0 8cqw 0 9cqw;
  font: 600 4.3cqw/1 var(--st-sans);
}

.still-phone-status svg {
  width: 17cqw;
  height: 4.4cqw;
  fill: currentColor;
}

.still-phone-content {
  position: absolute;
  inset: 16cqw 4.5cqw 23cqw;
  display: flex;
  flex-direction: column;
  gap: 3cqw;
}

.still-ev-date {
  margin-top: 2cqw;
  padding-left: 1.5cqw;
  color: var(--st-ink-2);
  font: 600 3.5cqw/1.2 var(--st-sans);
}

.still-ev-hello {
  margin-bottom: 1.5cqw;
  padding-left: 1.5cqw;
  font: 500 9.6cqw/1 var(--st-serif);
  letter-spacing: -0.01em;
}

.still-ev-card.lg-glass-surface {
  --lg-panel-radius: 5.6cqw;
  display: grid;
  gap: 3cqw;
  padding: 4cqw;
  border-radius: 5.6cqw;
}

.still-ev-row {
  display: flex;
  align-items: center;
  gap: 3cqw;
}

.still-ev-row > span:not(.still-ev-tile),
.still-ev-list li > span:not(.still-ev-tile) {
  display: grid;
  flex: 1;
  min-width: 0;
}

.still-ev-tile {
  display: grid;
  flex: none;
  place-items: center;
  width: 10cqw;
  height: 10cqw;
  border-radius: 3cqw;
  background: linear-gradient(150deg, #9483dc, #4e3c8c);
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 0.3);
  color: #fff;
}

.still-ev-tile .still-icon {
  width: 5.6cqw;
  height: 5.6cqw;
}

.still-ev-tile--rose {
  background: linear-gradient(150deg, #e09ab0, #8a4a6e);
}

.still-ev-tile--dusk {
  background: linear-gradient(150deg, #7f9be0, #3e4a8c);
}

.still-ev-tile--sun {
  background: linear-gradient(150deg, #f2c08e, #b4607a);
}

.still-ev-title {
  overflow: hidden;
  font: 600 4.2cqw/1.25 var(--st-sans);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.still-ev-meta {
  overflow: hidden;
  color: var(--st-ink-2);
  font: 400 3.4cqw/1.35 var(--st-sans);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.still-ev-progress.lg-progress {
  --lg-progress-height: 1.3cqw;
}

.still-ev-progress .lg-progress-track {
  box-shadow: none;
}

.still-ev-progress .lg-progress-fill {
  background: linear-gradient(90deg, #b9a8f0, var(--st-accent));
  box-shadow: none;
}

.still-ev-split {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 3cqw;
  padding-top: 3cqw;
  border-top: 1px solid rgb(255 255 255 / 0.08);
  font: 500 3.8cqw/1.2 var(--st-sans);
}

.still-ev-begin {
  display: inline-flex;
  align-items: center;
  align-self: center;
  gap: 2cqw;
  height: 11.5cqw;
  margin-top: auto;
  padding: 0 6cqw;
  border-radius: 99px;
  background: linear-gradient(180deg, #f1ebff, #d9ccfb);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / 0.7),
    0 6px 16px -6px rgb(10 4 30 / 0.6);
  color: var(--st-accent-ink);
  font: 600 3.9cqw/1 var(--st-sans);
}

.still-ev-begin .still-icon {
  width: 5cqw;
  height: 5cqw;
}

.still-ev-label {
  margin-top: 1cqw;
  padding-left: 1.5cqw;
  color: var(--st-ink-2);
  font: 600 3.5cqw/1 var(--st-sans);
}

.still-ev-list.lg-glass-surface {
  --lg-panel-radius: 5.6cqw;
  padding: 1cqw 4cqw;
  border-radius: 5.6cqw;
}

.still-ev-list li {
  display: flex;
  align-items: center;
  gap: 3cqw;
  padding: 2.7cqw 0;
}

.still-ev-list li + li {
  border-top: 1px solid rgb(255 255 255 / 0.08);
}

.still-ev-chevron.still-icon {
  width: 4.4cqw;
  height: 4.4cqw;
  color: var(--st-ink-2);
}

.still-phone .lg-switch {
  flex: none;
}

.still-phone-tabs.lg-glass-surface {
  --lg-panel-radius: 99px;
  position: absolute;
  left: 5cqw;
  right: 5cqw;
  bottom: 5cqw;
  display: flex;
  align-items: center;
  justify-content: space-around;
  height: 15.5cqw;
  border-radius: 99px;
}

.still-phone-tab {
  display: grid;
  justify-items: center;
  gap: 1cqw;
  color: var(--st-ink-2);
  font: 600 2.7cqw/1 var(--st-sans);
}

.still-phone-tab .still-icon {
  width: 6cqw;
  height: 6cqw;
}

.still-phone-tab[data-active] {
  color: var(--st-accent);
}

/* Voices */
.still-voices {
  text-align: center;
}

.still-voices-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(32px, 4vw, 64px);
  margin-top: 72px;
  text-align: left;
}

.still-voice {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 28px;
  padding-top: 28px;
  border-top: 1px solid var(--st-line);
}

.still-voice blockquote {
  margin: 0;
  color: var(--st-ink);
  font: italic 400 clamp(23px, 0.7vw + 16px, 27px) / 1.36 var(--st-serif);
}

.still-voice figcaption {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--st-ink-2);
  font-size: 14px;
  line-height: 1.4;
}

.still-voice figcaption b {
  display: block;
  color: var(--st-ink);
  font-weight: 600;
}

.still-avatar.lg-avatar {
  width: 40px;
  height: 40px;
  flex: none;
}

.still-avatar .lg-avatar-fallback {
  background: linear-gradient(140deg, var(--a), var(--b));
  color: var(--st-accent-ink);
  font: 700 13px/1 var(--st-sans);
  letter-spacing: 0.02em;
}

.still-avatar--lilac {
  --a: #efe7ff;
  --b: #c4a6e6;
}

.still-avatar--rose {
  --a: #ffe1ea;
  --b: #dc93ac;
}

.still-avatar--blue {
  --a: #dfe8ff;
  --b: #a4b3ee;
}

.still-rating {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  color: var(--st-ink-2);
  font-size: 15px;
}

.still-rating-marks {
  display: inline-flex;
  gap: 3px;
  color: var(--st-accent);
}

.still-rating-marks svg {
  display: block;
  width: 14px;
  height: 14px;
  fill: currentColor;
}

/* Pricing */
.still-pricing {
  text-align: center;
}

.still-pricing header {
  position: relative;
  z-index: 1;
}

.still-pricing .still-lede {
  margin-inline: auto;
}

.still-pricing-stage {
  position: relative;
  display: grid;
  justify-items: center;
  margin-top: 64px;
}

.still-pricing-art {
  position: absolute;
  inset: -48px calc(-1 * var(--st-pad)) -40px;
  overflow-x: clip;
  overflow-y: visible;
  pointer-events: none;
}

.still-pricing-moon {
  position: absolute;
  top: 20px;
  left: calc(50% + 160px);
  width: 250px;
  height: 250px;
  border-radius: 50%;
  background: radial-gradient(
    circle at 34% 32%,
    #f2ecff 0%,
    #d3c4f6 30%,
    #9c86dc 62%,
    #4f3d90 92%,
    #3d2f78 100%
  );
  box-shadow:
    inset -18px -22px 40px -10px rgb(30 20 70 / 0.45),
    0 0 80px 8px rgb(200 180 255 / 0.12);
}

.still-pricing-moon::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background:
    radial-gradient(14% 14% at 30% 58%, rgb(124 99 196 / 0.28), transparent 70%),
    radial-gradient(10% 10% at 62% 30%, rgb(124 99 196 / 0.22), transparent 70%),
    radial-gradient(18% 18% at 66% 70%, rgb(124 99 196 / 0.18), transparent 70%);
}

.still-pricing-orbit {
  position: absolute;
  top: 52%;
  left: 50%;
  width: 1100px;
  height: 260px;
  margin-left: -550px;
  border: 1px solid rgb(230 220 255 / 0.18);
  border-radius: 50%;
  transform: rotate(-8deg);
}

.still-pricing-art svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: #f6f1ff;
}

.still-plan.lg-glass-surface {
  --lg-panel-radius: 36px;
  position: relative;
  z-index: 2;
  width: min(100%, 560px);
  padding: 40px clamp(22px, 4vw, 48px) 32px;
  text-align: left;
}

.still-plan-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.still-plan-top h3 {
  font-size: 30px;
  line-height: 1.1;
}

.still-period.lg-segmented {
  width: auto;
  font-family: var(--st-sans);
  font-size: 13px;
}

/* A darker track, so both labels stay legible where the moon lights the glass. */
.still-period.lg-segmented::before {
  background-color: rgb(20 15 42 / 0.55);
}

.still-period .lg-segmented-item {
  padding: 6px 13px;
  font-weight: 600;
}

.still-price {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 14px;
  margin-top: 28px;
}

.still-price-figure {
  font: 500 clamp(60px, 4vw + 30px, 78px) / 1 var(--st-serif);
  font-variant-numeric: lining-nums tabular-nums;
  letter-spacing: -0.02em;
}

.still-price-per {
  color: var(--st-ink-2);
  font-size: 17px;
}

.still-price-note {
  margin-top: 8px;
  color: var(--st-ink-2);
  font-size: 15px;
}

.still-plan-list {
  display: grid;
  gap: 12px;
  margin: 28px 0 32px;
  padding: 28px 0 0;
  border-top: 1px solid var(--st-line);
}

.still-plan-list li {
  display: grid;
  grid-template-columns: 22px 1fr;
  gap: 12px;
}

.still-plan-list .still-icon {
  margin-top: 3px;
  color: var(--st-accent);
}

.still-plan-action,
.still-plan-action .still-store-trigger {
  width: 100%;
}

.still-plan-fine {
  margin-top: 16px;
  color: var(--st-ink-2);
  font-size: 14px;
  text-align: center;
}

.still-pricing-free {
  position: relative;
  margin-top: 48px;
  color: var(--st-ink-2);
}

/* StoreMenu */
.still-store-trigger .still-icon {
  width: 18px;
  height: 18px;
  transition: transform 320ms var(--lg-spring);
}

.still-store-trigger[data-state='open'] .still-icon {
  transform: rotate(180deg);
}

.still-store-menu.lg-menu-content {
  display: grid;
  gap: 2px;
  width: 272px;
  padding: 8px;
  border-radius: 22px;
  color: var(--st-ink);
  font-family: var(--st-sans);
  text-align: left;
}

.still-store-item.lg-menu-item {
  display: flex;
  align-items: center;
  gap: 14px;
  height: auto;
  padding: 12px;
  border-radius: 15px;
  color: var(--st-ink);
  text-decoration: none;
}

.still-store-item b {
  display: block;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
}

.still-store-item small {
  display: block;
  color: var(--st-ink-2);
  font-size: 13px;
  line-height: 1.4;
}

.still-store-item .still-icon {
  width: 22px;
  height: 22px;
  color: var(--st-accent);
}

/* Questions */
.still-faq-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: 24px;
  row-gap: 48px;
}

.still-faq-grid > header {
  position: sticky;
  top: 120px;
  grid-column: 1 / span 4;
  align-self: start;
}

.still-faq-list {
  grid-column: 6 / span 7;
  border-top: 1px solid var(--st-line);
}

.still-faq-item {
  border-bottom: 1px solid var(--st-line);
}

/* The answers are rows on the page, not glass of their own. */
.still-faq-list .lg-accordion-trigger {
  width: 100%;
  min-height: 0;
  padding: 24px 4px;
  border: 0;
  border-radius: 6px;
  background: none;
  box-shadow: none;
  color: var(--st-ink);
  font: 500 clamp(22px, 0.6vw + 16px, 26px) / 1.25 var(--st-serif);
  letter-spacing: 0;
  text-align: left;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.still-faq-list .lg-accordion-trigger:hover {
  background: none;
}

.still-faq-list .lg-accordion-trigger:focus-visible {
  outline: 2px solid var(--st-accent);
  outline-offset: 3px;
}

.still-faq-list .lg-accordion-trigger > span:first-child {
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.still-faq-list .lg-accordion-chevron {
  display: none;
}

.still-faq-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px var(--st-line);
  color: var(--st-accent);
  transition:
    transform 460ms var(--lg-spring),
    background-color 200ms;
}

.still-faq-icon .still-icon {
  width: 16px;
  height: 16px;
}

.still-faq-list .lg-accordion-trigger:hover .still-faq-icon {
  background: rgb(255 255 255 / 0.06);
}

.still-faq-list .lg-accordion-trigger[data-state='open'] .still-faq-icon {
  transform: rotate(45deg);
}

.still-faq-list .lg-accordion-content {
  --lg-panel-elevation-shadow: none;
  margin: 0;
  padding: 0;
  border-radius: 0;
  background: none;
  box-shadow: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.still-faq-list .lg-accordion-content::before,
.still-faq-list .lg-accordion-content::after,
.still-faq-list .lg-accordion-content > .lg-noise {
  display: none;
}

.still-faq-list .lg-accordion-content p {
  max-width: 60ch;
  padding: 0 4px 26px;
  color: var(--st-ink-2);
  font-size: 17px;
  line-height: 1.6;
}

/* Download */
.still-download {
  position: relative;
  isolation: isolate;
  padding-block: clamp(128px, 13vw, 196px) clamp(88px, 8vw, 128px);
  overflow-x: clip;
  text-align: center;
}

.still-download-art {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.still-download-stars {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 70%;
  fill: #f6f1ff;
}

.still-download-moon {
  position: absolute;
  top: clamp(40px, 6vw, 80px);
  left: calc(50% + clamp(90px, 16vw, 250px));
  width: clamp(64px, 6vw, 92px);
  height: auto;
  overflow: visible;
}

.still-download h2 {
  position: relative;
  font-size: clamp(46px, 4.4vw + 12px, 84px);
  line-height: 1.02;
  letter-spacing: -0.015em;
}

.still-download h2 em {
  color: var(--st-ink-3);
}

.still-download .still-lede {
  position: relative;
  margin-inline: auto;
}

.still-download-actions {
  position: relative;
  display: flex;
  justify-content: center;
  margin-top: 44px;
}

.still-download-actions::before,
.still-download-actions::after {
  content: '';
  position: absolute;
  left: 50%;
  width: 100vw;
  margin-left: -50vw;
  pointer-events: none;
}

.still-download-actions::before {
  top: 50%;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgb(255 214 228 / 0.24) 18%,
    rgb(255 228 236 / 0.75) 50%,
    rgb(255 214 228 / 0.24) 82%,
    transparent
  );
}

.still-download-actions::after {
  z-index: -1;
  top: 50%;
  height: 420px;
  margin-top: -260px;
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 24%, #000 76%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 24%, #000 76%, transparent);
  background:
    radial-gradient(
      36% 34% at 50% 62%,
      rgb(255 170 192 / 0.3),
      rgb(190 120 170 / 0.1) 50%,
      transparent 78%
    ),
    linear-gradient(
      180deg,
      transparent,
      rgb(110 61 98 / 0.16) 48%,
      rgb(163 98 124 / 0.22) 61.9%,
      rgb(40 26 58 / 0.3) 62%,
      transparent 92%
    );
}

.still-download-actions > * {
  position: relative;
  z-index: 1;
}

.still-download-note {
  position: relative;
  margin-top: 28px;
  color: var(--st-ink-2);
  font-size: 14px;
}

/* Footer */
.still-footer {
  padding: 72px 0 40px;
  border-top: 1px solid var(--st-line);
  color: var(--st-ink-2);
  font-size: 15px;
}

.still-footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 32px;
}

.still-footer-brand p {
  max-width: 30ch;
  margin-top: 14px;
}

.still-footer-brand .still-brand {
  color: var(--st-ink);
}

.still-footer h2 {
  margin-bottom: 16px;
  color: var(--st-ink);
  font: 600 13px/1.2 var(--st-sans);
  letter-spacing: 0.06em;
}

.still-footer ul {
  display: grid;
  gap: 10px;
}

.still-footer a {
  text-decoration: none;
  transition: color 200ms;
}

.still-footer a:hover {
  color: var(--st-ink);
}

.still-footer-base {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px 24px;
  margin-top: 64px;
  padding-top: 24px;
  border-top: 1px solid var(--st-line);
  font-size: 14px;
}

/* The demo note when a store has no link yet. */
.still-toast .lg-toast-root {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 20px 10px 10px;
}

.still-toast-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 50%;
  background: var(--st-accent);
  color: var(--st-accent-ink);
}

.still-toast-icon .still-icon {
  width: 17px;
  height: 17px;
}

.still-toast-text {
  color: var(--st-ink);
  font-size: 15px;
  line-height: 1.38;
}

/* Motion */
@keyframes still-rise {
  from {
    transform: translateY(var(--from, 24px));
  }
}

@keyframes still-reveal {
  from {
    transform: translateY(32px);
  }
}

@keyframes still-focus-in {
  from {
    filter: blur(10px);
    transform: translateY(8px);
  }
}

@keyframes still-fade {
  from {
    opacity: 0;
  }
}

@keyframes still-open {
  from {
    opacity: 0;
    transform: scaleX(0.2);
  }
}

@keyframes still-twinkle {
  50% {
    opacity: 0.22;
  }
}

@keyframes still-curve-draw {
  0%,
  24% {
    stroke-dashoffset: 1;
  }

  100% {
    stroke-dashoffset: 0;
  }
}

@keyframes still-curve-in {
  0%,
  70% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: no-preference) {
  :root:not([data-lg-reduce-motion='1']) .still-breath-rise {
    --from: 40px;
    animation: still-rise 1.8s var(--lg-ease-out) both;
  }

  :root:not([data-lg-reduce-motion='1']) .still-breath-ring {
    animation: still-fade 1.4s 0.3s var(--lg-ease-out) backwards;
  }

  :root:not([data-lg-reduce-motion='1']) :is(.still-sky-glow, .still-sky-path, .still-sky-glints) {
    animation: still-fade 2s var(--lg-ease-out) backwards;
  }

  :root:not([data-lg-reduce-motion='1']) .still-sky-horizon {
    animation: still-open 1.6s 0.1s var(--lg-ease-out) backwards;
  }

  :root:not([data-lg-reduce-motion='1']) .still-hero-line {
    animation: still-focus-in 1.1s 0.15s var(--lg-ease-out) both;
  }

  :root:not([data-lg-reduce-motion='1']) .still-hero-line--soft {
    animation-delay: 0.45s;
  }

  :root:not([data-lg-reduce-motion='1']) :is(.still-hero-lede, .still-breath-status) {
    animation: still-focus-in 0.9s 0.8s var(--lg-ease-out) both;
  }

  :root:not([data-lg-reduce-motion='1']) .still-breath-controls {
    --from: 14px;
    animation: still-rise 0.9s 1s var(--lg-ease-out) both;
  }

  /* The page's one quiet loop: a few stars and glints shimmer while the hero is on screen. */
  :root:not([data-lg-reduce-motion='1']) .still-sky .still-twinkle {
    animation: still-twinkle 16s ease-in-out infinite;
  }

  .still-hero[data-away] .still-sky .still-twinkle {
    animation-play-state: paused;
  }

  @supports (animation-timeline: view()) {
    /* Sections rise into place as they scroll in; they move only, so their glass keeps its
       backdrop. */
    :root:not([data-lg-reduce-motion='1']) .still-rise {
      animation: still-reveal linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 80%;
    }

    /* The breath draws itself as it scrolls in. Off screen, and without scroll timelines, it
       stays drawn. */
    :root:not([data-lg-reduce-motion='1'])
      :is(.still-curve-line, .still-curve-area, .still-curve-dot) {
      animation: still-curve-draw linear forwards;
      animation-timeline: --still-curve;
      animation-range: entry 0% cover 54%;
    }

    :root:not([data-lg-reduce-motion='1']) :is(.still-curve-area, .still-curve-dot) {
      animation-name: still-curve-in;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .still-header.lg-header,
  .still-story,
  .still-faq-icon,
  .still-store-trigger .still-icon,
  .still-breath-orb,
  .still-breath-trace,
  .still-breath-tick,
  .still-hero-title,
  .still-hero-lede,
  .still-phone-warm,
  .still-skip {
    transition: none !important;
  }
}

:root[data-lg-reduce-motion='1']
  :is(
    .still-header.lg-header,
    .still-story,
    .still-faq-icon,
    .still-breath-orb,
    .still-breath-trace,
    .still-breath-tick,
    .still-hero-title,
    .still-hero-lede,
    .still-phone-warm
  ) {
  transition: none !important;
}

/* Layout */
@media (max-width: 899px) {
  .still-practice-head,
  .still-practice-body,
  .still-evenings-copy,
  .still-evenings-phone,
  .still-faq-grid > header,
  .still-faq-list {
    grid-column: 1 / -1;
  }

  .still-practice-body {
    font-size: 17px;
  }

  .still-curve {
    margin-top: 40px;
  }

  .still-curve-line,
  .still-curve-dot {
    stroke-width: 6;
  }

  .still-curve-labels b {
    font-size: 20px;
  }

  .still-curve-labels span {
    font-size: 13px;
  }

  .still-facts {
    grid-template-columns: 1fr;
    gap: 32px;
    margin-top: 64px;
  }

  .still-scenes {
    grid-template-columns: 1fr;
    gap: 20px;
    margin-top: 48px;
  }

  .still-carousel-bar {
    flex-direction: column;
    align-items: flex-start;
    gap: 24px;
  }

  .still-voices-grid {
    grid-template-columns: 1fr;
    gap: 40px;
    margin-top: 56px;
  }

  .still-faq-grid > header {
    position: static;
  }

  .still-footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .still-footer-brand {
    grid-column: 1 / -1;
  }

  .still-pricing-moon {
    left: auto;
    right: -70px;
    width: 240px;
    height: 240px;
  }
}

@media (max-width: 859px) {
  .still-hero {
    --nav-h: 82px;
  }
}

@media (max-width: 600px) {
  .still-sky-stars .still-sky-wide,
  .still-sky-venus,
  .still-sky-land {
    display: none;
  }

  .still-rating {
    flex-direction: column;
    gap: 8px;
  }

  .still-curve-labels p {
    padding-left: 8px;
  }

  .still-curve-labels b {
    font-size: 18px;
  }

  .still-scene-body.lg-glass-surface {
    padding: 20px 18px 16px;
  }

  .still-scene-title {
    font-size: 28px;
  }

  .still-download h2 em {
    display: block;
  }

  .still-footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .still-footer-base {
    flex-direction: column;
  }
}
